WITH joined AS (SELECT s.*, b.store_name, b.opened_date, b.region FROM inventory s LEFT JOIN stores b ON s.store_id = b.id WHERE b.store_name LIKE '%Mal%') SELECT DATE_TRUNC('MONTH', last_restock) AS activity_month, region, CASE WHEN quantity >= 262 THEN 'HIGH' ELSE 'LOW' END AS quantity_tier, COUNT(DISTINCT store_id) AS distinct_store_ids, COUNT(DISTINCT product_id) AS distinct_product_ids FROM joined GROUP BY DATE_TRUNC('MONTH', last_restock), region, CASE WHEN quantity >= 262 THEN 'HIGH' ELSE 'LOW' END;
